bool CoreKey::operator==(const CoreKey&x)const noexcept{return window_t==x.window_t&&window_h==x.window_h&&window_w==x.window_w&&grid_t==x.grid_t&&grid_h==x.grid_h&&grid_w==x.grid_w&&variant==x.variant;}
bool DiTBlockConfig::operator==(const DiTBlockConfig& x)const noexcept{return hidden_dim==x.hidden_dim&&txt_dim==x.txt_dim&&heads==x.heads&&head_dim==x.head_dim&&configured_rope_dim==x.configured_rope_dim&&effective_rotary_dim==x.effective_rotary_dim&&identity_tail_dim==x.identity_tail_dim&&mlp_hidden_dim==x.mlp_hidden_dim&&q_max==x.q_max&&head_pairs==x.head_pairs&&norm_eps==x.norm_eps&&mlp_type==x.mlp_type&&is_last_layer==x.is_last_layer;}
const NcnnModelFiles* DiTBlockArtifact::model(const std::string& n)const noexcept{auto it=models.find(n);return it==models.end()?nullptr:&it->second;}
const SingleModelArtifact* CoreInfo::single_model()const noexcept{return std::get_if<SingleModelArtifact>(&artifact);}
const StagedHeadMergeArtifact* CoreInfo::staged_head_merge()const noexcept{return std::get_if<StagedHeadMergeArtifact>(&artifact);}
const DiTBlockArtifact* CoreInfo::dit_block()const noexcept{return std::get_if<DiTBlockArtifact>(&artifact);}
const AuxiliaryInputConfig* CoreInfo::auxiliary()const noexcept{return std::get_if<AuxiliaryInputConfig>(&auxiliary_inputs);}
bool ArtifactRegistry::scan(const std::filesystem::path&r,std::string&e){return scan(std::vector<std::filesystem::path>{r},e);}
bool ArtifactRegistry::scan(const std::vector<std::filesystem::path>&rs,std::string&e){std::vector<CoreInfo>x;try{for(auto&r:rs){if(!std::filesystem::is_directory(r))throw std::runtime_error("root not directory: "+r.string());for(auto&z:std::filesystem::directory_iterator(r))if(z.is_directory()&&std::filesystem::exists(z.path()/"metadata.json")){CoreInfo c;try{c=read(z.path());}catch(const std::exception&error){throw std::runtime_error((z.path()/"metadata.json").string()+": "+error.what());}for(auto&q:x)if(q.key==c.key)throw std::runtime_error("duplicate key: "+c.name);x.push_back(std::move(c));}}std::sort(x.begin(),x.end(),[](auto&a,auto&b){return a.name<b.name;});cores_=std::move(x);e.clear();return true;}catch(const std::exception&z){e=z.what();return false;}}
const CoreInfo* ArtifactRegistry::lookup(const CoreKey&k)const noexcept{for(auto&x:cores_)if(x.key==k)return&x;return nullptr;}
std::vector<CoreInfo> ArtifactRegistry::list()const{return cores_;}std::size_t ArtifactRegistry::size()const noexcept{return cores_.size();}
